const escape = value => String(value).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
export function accountMarkup(s) {
 const status={connecting:'Connecting…',loading:'Loading journey…',guest:'Saved on this device',saving:'Saving…',saved:'Cloud saved',pending:'Save pending',offline:'Offline · saved on device',choice:'Choose your save','local-error':'Export a backup'}[s.phase]||s.phase;
 return `<div class="account-identity"><span class="account-light ${s.phase==='saved'?'synced':''}"></span><strong>${s.user?escape(s.user.email||'Student account'):'Guest journey'}</strong></div><span class="account-status" role="status">${escape(status)}</span>${s.message?`<p class="account-message">${escape(s.message)}</p>`:''}${s.user?`<div class="account-actions"><button data-account="open">Account</button>${s.phase==='offline'?'<button data-account="retry">Retry save</button>':''}</div>`:s.configured?'<button class="account-login" data-account="login">Sign in with Google</button>':'<span class="account-status">Cloud login awaiting setup</span>'}`;
}
export function accountDialogMarkup(s,choices) {
 const count=p=>Object.values(p?.academicRecords||{}).filter(r=>r.status==='COMPLETED').length;
 if(s.choice==='import')return `<h2>Continue your journey</h2><p>This browser already has guest progress. Choose how to begin your account save. Your guest copy stays on this device.</p><div class="account-choice"><button class="primary" data-account="guest">Use guest progress</button><button class="secondary" data-account="new">Start a new journey</button></div>`;
 if(s.choice==='conflict')return `<h2>Two journeys, one account</h2><p>Another device changed your cloud save. Choose which copy to continue with.</p><div class="account-choice"><button class="primary" data-account="cloud">Use cloud copy · ${count(choices.cloud)} completed</button><button class="secondary" data-account="device">Use this device · ${count(choices.device)} completed</button></div><p class="card-note">Using this device replaces the cloud copy after confirmation. A backup of the cloud copy is retained on this device.</p>`;
 return `<h2>Your account</h2><p>${escape(s.user?.email||'Save your journey across devices with Google sign-in.')}</p><p class="card-note">Guest and account journeys are stored separately. Specialization acceptance remains self-reported.</p>${s.user?'<button class="secondary" data-account="logout">Sign out</button>':'<button class="primary" data-account="login">Sign in with Google</button>'}`;
}
